import{c as t,Q as i,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"s1: Simple Test-Time Scaling","description":"","frontmatter":{"url":"https://arxiv.org/abs/2501.19393","title":"s1: Simple Test-Time Scaling","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2501.19393,"authors":["Niklas Muennighoff","Zitong Yang","Weijia Shi","Xiang Lisa Li","Li Fei-Fei","Hannaneh Hajishirzi","Luke Zettlemoyer","Percy Liang","Emmanuel Candès","Tatsunori Hashimoto"],"pdf_path":"pdfs/2501.19393.pdf","published_date":"2025-01-31T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-01-31-s1-simple-test-time-scaling-2501-19393.md","filePath":"research/papers/2025-01-31-s1-simple-test-time-scaling-2501-19393.md","lastUpdated":1785909234000}'),r={name:"research/papers/2025-01-31-s1-simple-test-time-scaling-2501-19393.md"};function o(s,e,l,c,d,g){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="s1-simple-test-time-scaling" tabindex="-1">s1: Simple Test-Time Scaling <a class="header-anchor" href="#s1-simple-test-time-scaling" aria-label="Permalink to &quot;s1: Simple Test-Time Scaling&quot;">​</a></h1><p><strong>Authors:</strong> Niklas Muennighoff, Zitong Yang, Weijia Shi, Xiang Lisa Li, Li Fei-Fei, Hannaneh Hajishirzi, Luke Zettlemoyer, Percy Liang, Emmanuel Candès, Tatsunori Hashimoto <strong>Year:</strong> 2025 <strong>Submitted:</strong> January 31, 2025 <strong>Venue:</strong> arXiv preprint (Stanford, UW, Meta) <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2501.19393" target="_blank" rel="noreferrer">https://arxiv.org/abs/2501.19393</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Test-time compute is a new axis for scaling language model performance beyond what is achievable through training-time compute alone. We present s1, a simple and effective approach to test-time scaling that requires only supervised fine-tuning (SFT) on a small curated dataset and a lightweight inference-time mechanism called budget forcing. We curate s1K, a dataset of 1,000 questions with associated reasoning traces, selected from a larger candidate pool using three criteria: difficulty (problems that challenge frontier models), diversity (broad coverage of domains), and quality (verified correct solutions with high-quality reasoning traces from Gemini Thinking Experimental).</p><p>We introduce budget forcing, a technique that controls test-time compute by appending &quot;Wait&quot; tokens to extend or forcefully truncate the model&#39;s chain-of-thought generation. This simple mechanism enables the model to engage in additional verification and self-correction during extended thinking, without any changes to model weights. Fine-tuning Qwen2.5-32B-Instruct on s1K with budget forcing at inference time produces s1-32B, which exceeds o1-preview on competition mathematics benchmarks (AIME24, MATH500) by up to 27%, using sequential scaling of test-time compute. We release the model, dataset, and code publicly.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Budget forcing</strong>: A simple inference-time technique that extends or truncates chain-of-thought generation by appending or removing &quot;Wait&quot; tokens — enabling control of test-time compute without modifying model weights or requiring RL.</li><li><strong>s1K dataset</strong>: A 1,000-example training set curated from 59,000 candidates using difficulty, diversity, and quality criteria; sufficient to elicit strong reasoning after SFT on a 32B base model.</li><li><strong>Sequential test-time scaling</strong>: Demonstrates that thinking length (controlled via budget forcing) is positively correlated with accuracy on hard competition math problems — a direct empirical demonstration of sequential compute scaling.</li><li><strong>Surpasses o1-preview with 32B model</strong>: s1-32B exceeds o1-preview on AIME24 (56.7% vs. 44.6%) and MATH500, using a fraction of the training investment.</li><li><strong>Full open-source release</strong>: Model weights (s1-32B), s1K dataset, and inference code released publicly, enabling community reproduction without proprietary RL infrastructure.</li><li><strong>Validation that SFT alone suffices for o1-class reasoning</strong>: Shows that reasoning capability from a strong teacher (Gemini Thinking) can be transferred via SFT + inference-time control, without RL training.</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>The s1 approach consists of two components: a curated training dataset and an inference-time compute control mechanism. For <strong>dataset curation</strong>, the authors start from a pool of approximately 59,000 questions sourced from existing math and science benchmarks, competitions, and educational resources. Questions are filtered using three criteria: (1) <em>difficulty</em> — problems that frontier models (GPT-4o, Gemini) answer incorrectly; (2) <em>diversity</em> — selected to span different mathematical subfields and reasoning types; (3) <em>quality</em> — reasoning traces generated by Gemini Thinking Experimental are verified for correctness and coherence. The final s1K dataset contains 1,000 examples with full chain-of-thought reasoning traces. Qwen2.5-32B-Instruct is fine-tuned on s1K using standard SFT.</p><p>At inference time, <strong>budget forcing</strong> controls how much computation the model performs before emitting a final answer. To <em>extend</em> thinking, the string &quot;Wait&quot; is appended to the model&#39;s partial generation whenever it attempts to terminate — forcing continued chain-of-thought reasoning. To <em>truncate</em> thinking, the end-of-thinking token is injected early. This mechanism allows a single trained model to operate across a spectrum of compute budgets without retraining. Extended thinking with budget forcing enables the model to catch errors, verify intermediate steps, and explore alternative solution paths, improving accuracy on hard problems.</p><p>The paper frames this as <strong>sequential test-time scaling</strong>: the model generates one long, iterative reasoning chain rather than sampling N independent chains in parallel (parallel scaling). Sequential scaling is orthogonal to parallel scaling and can be combined with it. Budget forcing is a minimal, implementation-level technique for controlling sequential compute — requiring no modifications to training, architecture, or reward modeling infrastructure.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li><strong>AIME24</strong>: s1-32B achieves 56.7% pass@1, compared to 44.6% for o1-preview — a 27% relative improvement.</li><li><strong>MATH500</strong>: s1-32B achieves 93.0% accuracy, exceeding o1-preview (85.5%) and matching o1-mini (90.0%).</li><li><strong>Thinking length vs. accuracy</strong>: Positive correlation between budget-forced thinking length and accuracy on hard AIME problems — empirically validating the sequential compute scaling hypothesis.</li><li><strong>s1K ablations</strong>: Quality and difficulty criteria are most critical for dataset selection; diversity provides marginal but consistent additional benefit.</li><li><strong>Reasoning trace source matters</strong>: Gemini Thinking Experimental traces outperform traces from other models (Claude 3.5, GPT-4o) on both answer correctness and reasoning coherence metrics.</li><li><strong>Model size scaling</strong>: Larger base models (32B &gt; 7B) benefit more from s1K fine-tuning, suggesting a capability threshold required to absorb complex reasoning traces.</li></ul><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>Budget forcing via &quot;Wait&quot; token appending is a heuristic mechanism; the model was not explicitly trained to respond to this signal, and behavior may be brittle on different base models.</li><li>s1K is focused on math and STEM; generalization of the dataset curation methodology to other domains (law, coding, scientific reasoning) is demonstrated only partially.</li><li>The approach relies on access to a strong reasoning trace generator (Gemini Thinking Experimental); the quality ceiling of s1K is bounded by the teacher model.</li><li>Sequential scaling via budget forcing has diminishing returns beyond a certain thinking length; the optimal budget varies by problem and requires a budget allocation strategy.</li><li>Future work includes extending budget forcing to domains beyond math, combining sequential and parallel scaling, and developing automated difficulty estimation for adaptive budget allocation.</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>s1 demonstrates that <strong>o1-class reasoning is accessible without RL infrastructure</strong>, requiring only a curated SFT dataset of 1,000 examples and a one-line inference modification (appending &quot;Wait&quot; tokens). For practitioners, this dramatically lowers the barrier to deploying reasoning-capable models. The budget forcing mechanism provides a direct, interpretable knob for trading inference latency against accuracy — a highly practical property for production systems with varying cost/quality requirements. The full open-source release (model + data + code) makes s1-32B a reproducible baseline for the community. The paper also provides one of the clearest empirical demonstrations that thinking length causally improves accuracy on hard problems, validating the core premise of the test-time compute scaling paradigm.</p>',23)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
